function atualizarGrupo(dt) {
  // Fora do capítulo 2 não há fila: a arte é a pessoa de Palmares e ela não anda nos outros
  // dois. Quem fecha o capítulo deixa o grupo lá, que é onde ele veio ficar.
  if (!capGente()) {
    if (grupo.length || ficando.length || S.grupo) { grupo.length = 0; ficando.length = 0; S.grupo = 0; }
    return;
  }
  const v = velocidadeMundo();
  grupo.forEach(function (c, i) {
    const alvo = worldX + HX - (GRUPO_FRENTE + i * GRUPO_VAO);
    const dx = alvo - c.x;
    // Velocidade própria, nunca zero: 0,55× enquanto ainda está à frente do lugar dela (a rua
    // faz o resto), até 1,25× para fechar o vão quando alguém sai da frente da fila.
    const vp = dx < 0 ? v * 0.55 : dx > 0 ? v * Math.min(1.25, 1 + dx * 0.08) : v;
    const p = vp * dt;
    c.x += p; c.d += p;
    if (dx > 0 && c.x > alvo) c.x = alvo;     // apressou o passo: não passa do lugar dela
  });
  ficando.forEach(function (c) { const p = v * 0.42 * dt; c.x += p; c.d += p; });
  ficando = ficando.filter(function (c) { return c.x - worldX > -40; });
}
// Ao carregar um save, a fila volta como estava. Ela é REMONTADA e não guardada: o que o save
// carrega é quantas, e o resto (lugar, altura, fase da passada) nasce de novo aqui — nada
// disso é informação que valha a pena confiar a `localStorage`, que é entrada não confiável.
function semearGrupo() {
  grupo = []; ficando = [];
  const n = Math.max(0, Math.min(GRUPO_MAX, S.grupo | 0));
  for (let i = 0; i < n; i++) {
    grupo.push({ x: worldX + HX - (GRUPO_FRENTE + i * GRUPO_VAO),
      d: Math.random() * 60, esc: 0.82 + Math.random() * 0.13 });
  }
}

function atualizarDrops(dt) {
  drops.forEach(function (d) {
    d.t += dt;
    // The hero collects a drop just by running over it — full value and full focus, the
    // same as an aimed tap. So essentially everything on the ground now gets picked up.
    if (!d.morto && d.wx - worldX <= HX + 8) { coletarDrop(d, false); return; }
    // U4 still grabs whatever is somehow ahead of the hero (a super/call drop spawned past
    // him), sharing half — but the pass-over above means this rarely fires now.
    if (S.u3 && d.t > CFG.dropAuto && !d.morto) coletarDrop(d, true);
    if (d.t > CFG.dropVida) d.morto = true;
  });
  drops = drops.filter(function (d) { return !d.morto && d.wx - worldX > -20; });
}

function atualizarChamada(dt) {
  // owner: remove mutirão. Neutered: never opens a call, never advances timers, so the pot
  // and the mutirão-bonus never enter play. drawing code, DOM and CSS untouched.
}


// `auto`     — a shot the wand fired by itself: earns, but never heals.
// `naoConta` — a swing that is not the player's hand (the neighbours' auto-taps). It plays
//              out identically; it just cannot charge the super, so a phone on a table
//              never builds one.
function clicar(auto?, naoConta?, semAnim?) {
  const g = ganhoClique();
  S.energia += g; S.energiaTotal += g;
  // the team recovers while you organise together, not while you burn them out:
  // healing only in GO STEADY is what keeps holding the button from erasing tiredness.
  // A shot the wand fires by itself is not people helping each other, so it never heals —
  // that keeps automatic output structurally incapable of paying for GO FAST.
  // The combo counter advances for EVERY swing, auto-helpers included, so reach and damage
  // are unchanged and the economy sim stays byte-identical (it models neither jumpT nor
  // attackType). But only a REAL tap moves the hero: the neighbours' auto-taps (U4, 2/s) and
  // the wand skill used to drive the whole 3-hit combo, so the character leapt on its own
  // every ~1.5s and the frame read as bugged in production. The visible swing and leap now
  // fire on player taps only; the auto-helpers still deal their damage below.
  // Owner: the leap comes on every FIFTH swing, not every third. Four ordinary casts, then
  // she goes up.
  const PASSOS = 5, SALTO = PASSOS - 1;
  const passo = combo; combo = (combo + 1) % PASSOS;
  // semAnim: the swing that comes with a JUMP. It earns and it damages, but it leaves the
  // pose alone — she is already in the air, and stamping an attack frame over the leap would
  // cut the arc in half.
  if (!auto && !semAnim) {
    // only two cast poses exist, so the four ordinary beats alternate between them
    attackType = passo % 2;
    // O quinto tempo NÃO pula mais. Pular era efeito colateral de alcançar cinco vezes, e
    // isso tirava o pulo das mãos de quem joga: a personagem saía do chão sem ninguém pedir,
    // no meio de atender alguém. Pulo agora é só da metade esquerda da tela, que é a única
    // parte da entrada que o jogador controla de propósito.
    // O quinto tempo continua sendo o tempo forte — alcance 96 e dano dobrado, logo abaixo —
    // só que ele acontece no chão.
    attackT = ATKF;
  }
  // reach covers the whole queue (three troubles, one body-width apart) — otherwise the
  // one at the back is unhittable from the button and the road never clears
  const range = passo === SALTO ? 96 : 80, dmg = passo === SALTO ? 2 : 1;
  // UMA DE CADA VEZ, e é o que faz existir escolha. O golpe atingia TODAS as que estivessem
  // no alcance, e o alcance de 80 px cobre metade da tela: com as coisas paradas esperando,
  // isso significa que segurar o botão atendia a fila inteira de graça. Medido antes desta
  // linha: 21 de 21 andando e 28 de 28 correndo, ou seja fração 1,00 nos dois casos — o
  // oposto de "há mais gente esperando do que tempo para atender".
  //
  // Atender uma por vez é o que um par de mãos faz, e é a leitura certa também pelo §2: você
  // chega até alguém, não dispersa um gesto sobre um grupo. A mais próxima primeiro, porque é
  // a que está prestes a ficar para trás — e o alcance continua sendo 80 px, então quem está
  // no fim da fila continua alcançável, só que na vez dela.
  let alvo: Mob | null = null, maisPerto = 1e9, alvoSx = 0;
  mobs.forEach(function (m) {
    // `dying` conta oito quadros e zera em drawMobs(), que marca `dead`; quem varre `dead` é o
    // laço de atualizarMobs, no quadro seguinte. Entre as duas coisas existe uma fresta, e o
    // relógio do segurar (145 ms) não é o relógio do quadro: um toque que caísse nessa fresta
    // achava uma chegada com dying 0 e hp 0, batia de novo e chamava registrarChegada(true)
    // uma SEGUNDA vez pela mesma pessoa. Medido: 19 alcances contados para 17 chegadas
    // alcançadas em 30 s, 12% de inflação em cima da média que o mundo lê.
    if (m.dying > 0 || m.dead || m.hp <= 0) return;
    const sx = m.wx - worldX;
    if (sx > HX - 6 && sx < HX + range && sx < maisPerto) { maisPerto = sx; alvo = m; alvoSx = sx; }
  });
  if (alvo) {
    // O fluxo de análise do TS não enxerga atribuição feita dentro do callback do forEach
    // acima, então para ele `alvo` ainda seria null aqui. É limite do compilador, não do código.
    const m = alvo as Mob, sx = alvoSx;
    // No capítulo 2 quem está ali é uma PESSOA, e três coisas deste bloco são gramática de
    // combate: o pisca branco no corpo, o estilhaço, e o empurrão. Todas ficam de fora.
    const gente = capGente();
    m.hp -= dmg; if (!gente) m.flash = 5;
    // O empurrão de 10 px por golpe era o que, sozinho, tornava a janela infinita: a 7
    // golpes/s ele devolve 70 px/s, mais do que os 38–77 px/s com que a caminhada afasta.
    // Nada saía do alcance enquanto estivesse apanhando. Em quem está PARADA esperando ele
    // também é a imagem errada — ninguém empurra para trás quem veio pedir ajuda.
    if (!m.parado && !gente) m.wx += 10;
    if (gente) {
      // dois pontos de luz morna subindo dos pés: diz "estou chegando até você" sem estilhaço,
      // sem clarão e sem cor de alarme. `grav` negativo os faz subir em vez de cair.
      for (let i = 0; i < 2; i++) {
        parts.push({ x: sx + 4 + (Math.random() - 0.5) * 10, y: GROUND - 8,
          vx: (Math.random() - 0.5) * 8, vy: -16 - Math.random() * 10,
          life: 0.45 + Math.random() * 0.2, c: "#f3dda6", grav: -8 });
      }
    } else {
      burst(sx + 8, GROUND - 14, 5, m.type === "cash" ? ["#ffcd75", "#ffe9b0"]
        : m.type === "barrel" ? ["#7fb356", "#b5e08c"] : ["#9a92aa", "#7a7288"]);
    }
    if (m.hp <= 0) {
      // Microdica 2 (usabilidade, achado 5): a primeira espera ATENDIDA arma a seta; ela
      // dispara quando o que ficou no chão for recolhido e o contador de cima encher —
      // ver coletarDrop(), que é onde o alvo da seta passa a existir.
      if (m.parado && !dicaSetaVista && dicasValem()) dicaSetaArmada = true;
      // Objeto se dissipa em oito quadros; PESSOA não se dissipa. Ela sai da rua e entra na
      // fila que anda atrás da protagonista, sem sumir de quadro em nenhum momento. `dead`
      // é o mesmo caminho que atualizarMobs já varre, e não conta nada por si.
      // o +5 é o mesmo deslocamento com que ela vinha sendo desenhada: sem ele a figura
      // saltaria 5 px para a esquerda no quadro em que vira para andar junto
      if (gente) { m.dead = true; acolherPessoa(m.wx + 5, m.esc); } else m.dying = 8;
      registrarChegada(true);     // alcançada: o mundo responde a isto tanto quanto ao que passa
      soltarDrop(m, sx);          // o que ela TROUXE fica no chão; a pessoa, não
      burst(sx + 8, GROUND - 14, gente ? 12 : 16, gente ? ["#f3dda6", "#fbeec4", "#e6c98a"]
        : m.type === "cash" ? ["#ffcd75", "#ffe9b0", "#e8edf6"]
        : m.type === "barrel" ? ["#7fb356", "#b5e08c", "#6fdd94"] : ["#9a92aa", "#8d5bd6", "#6fdd94"]);
      if (!auto) somAtendida();
    }
  }
  // O som é do GESTO DE QUEM JOGA. A ajuda automática do U3 bate 2 vezes por segundo e a mão
  // de ninguém está ali: sonorizá-la faria o jogo tocar sozinho numa mesa, que é a definição
  // de som que cansa. `alvo` decide o timbre — ver somAlcance().
  if (!auto) somAlcance(!!alvo);
  // only the player's own taps put a "+N" over the hero — auto-help at 2/s (or the wand at
  // 10/s) used to spew a float every tick, which read as the frame twitching.
  // Com u1, os toques em sequência somam num float só (ver a declaração de floatToque):
  // a vida renovada é mais curta (28) para que, solto o botão, o número saia logo de cena.
  if (!auto) {
    if (S.u1 && floatToque && floats.indexOf(floatToque) >= 0) {
      floatToqueSoma += g;
      floatToque.txt = "+" + (floatToqueSoma % 1 ? floatToqueSoma.toFixed(1) : String(floatToqueSoma));
      floatToque.life = 28;
      // ele sobe como todo float, mas um número que se renova por minutos subiria até sair da
      // tela ainda vivo: sobe os primeiros ~18 px e segura ali, tiquetaqueando
      if (floatToque.y < GROUND - 52) floatToque.y = GROUND - 52;
    } else {
      floatToqueSoma = g;
      floatToque = { x: HX + 14, y: GROUND - 34, txt: "+" + g.toFixed(1), life: S.u1 ? 28 : 40 };
      floats.push(floatToque);
    }
  }
  desenhar();
}
// Trocar o ritmo alterna andar e correr. A faixa de texto que anunciava o que a troca custava
// e o que comprava lia quatro identificadores que não existiam — `delta`, `saudeFim`,
// `fracaoPerdida` e `rampaCheia` — restos da economia passiva do jogo anterior. Em `use
// strict` isso é ReferenceError, não `undefined`: o card estourava em TODO clique, nos dois
// sentidos, e o HUD só se corrigia por acidente no tique seguinte do laço. Ver o teste do
// card em test/smoke.js — ele agora CLICA no card, que é o que faltava para pegar isto.
function definirModo(m) {
  if (S.modo === m) return;
  S.modo = m;
  const rapido = m === "carvao";
  // The rhythm decides how fast the street goes past and which cycle she runs. It used to
  // report a rate change, a settling rate and a team-health figure as well; those belonged to
  // the passive economy and all of them read zero now.
  floats.push({ x: HX - 10, y: GROUND - 44, txt: rapido ? "CORRER!" : "ANDAR!", life: 52 });
  burst(HX + 6, GROUND - 20, 26, rapido ? ["#ff6b57", "#ffcd75", "#ffe9b0"] : ["#38b764", "#6fdd94", "#b5e08c"]);
  for (let i = 0; i < 14; i++) {   // a column of sparks going up: revving, or exhaling
    parts.push({ x: HX + 4 + (Math.random() - 0.5) * 26, y: GROUND - 4,
      vx: (Math.random() - 0.5) * (rapido ? 40 : 16), vy: -(rapido ? 70 : 34) - Math.random() * 40,
      life: 0.7 + Math.random() * 0.4, c: rapido ? "#ff6b57" : "#6fdd94", grav: rapido ? 60 : 22 });
  }
  desenhar();
}
// screen-level punch that belongs to the HUD, not to the scene: a full-frame wash and a
// pop on the chips that just changed meaning
// owner: piscar() removed — the full-frame wash is gone with the rest of the screen effects.
function comprar(u, custo) {
  if (!S[u] && S.energia >= custo) { S.energia -= custo; S[u] = true; desenhar(); }
}

// ============================================================
// ---------- SOM ----------
//
// TUDO SINTETIZADO. Nenhum byte de áudio no arquivo: osciladores, envelopes e ruído filtrado,
// escritos aqui. Duas razões e as duas pesam. O index.html já passa de 3,5 MB e um punhado de
// efeitos gravados custaria centenas de KB; e som sintetizado é o vocabulário nativo do pixel
// art — cada efeito é meia dúzia de números que se afinam um a um.
//
// O QUE ESTE MÓDULO NÃO TEM, E É REGRA E NÃO ESQUECIMENTO: nenhum som de dano, de dor, de
// golpe ou de morte. O verbo do jogo é ALCANÇAR. Quem atravessa a tela pede ajuda, e no
// capítulo 2 é GENTE — som de impacto em pessoa é a linha do §2.2 e não se cruza. Por isso o
// som de alcançar é uma NOTA, e o de atender alguém até o fim é um intervalo que RESOLVE:
// a leitura sonora é "cheguei até você", nunca "bati em você".
//
// ARQUITETURA. Um AudioContext só, criado no PRIMEIRO toque e nunca antes — navegador nenhum
// deixa tocar sem gesto, e tentar antes derruba erro no console (o smoke test reprova erro de
// console). Cada som cria os nós de que precisa, agenda o envelope e se desconecta sozinho no
// `onended`: nada fica pendurado no grafo. O mestre é um GainNode único, e desligar o som no
// AJUSTES é o mesmo caminho que não tocar nada — a checagem é na porta de cada função.
let audCtx: AudioContext | null = null;
let audMestre: GainNode | null = null;
let audRuido: AudioBuffer | null = null;
// Volume BAIXO por padrão: alguém abre o jogo no ônibus. Isto multiplica todos os efeitos, e
// os ganhos individuais lá embaixo são relativos a ele.
const AUD_VOL = 0.22;
// Teto de vozes por quadro. Segurar o botão dá ~7 alcances/s e cada um é uma voz; o teto está
// aqui para o caso patológico (fila cheia + passo + drop no mesmo instante), não para o normal.
let audVozes = 0, audVozesQuadro = -1;
// `resume()` devolve uma PROMESSA, e ela REJEITA quando o navegador ainda não viu um gesto de
// verdade — evento sintético não destrava nada. Promessa rejeitada sem `catch` vira erro não
// tratado no console, e o smoke test reprova erro de console: o `catch` vazio aqui não é
// desleixo, é o tratamento. Silêncio é a degradação certa para som que não pode tocar.
function retomarAudio() {
  if (!audCtx) return;
  try {
    const p = audCtx.resume() as any;
    if (p && typeof p.catch === "function") p.catch(function () {});
  } catch (e) {}
}
function audioPronto(): AudioContext | null {
  if (!S.som) return null;
  if (!audCtx) return null;
  // Abas que voltam do segundo plano acordam com o contexto suspenso. Retomar é barato e
  // silencioso; se o navegador recusar, o som simplesmente não sai e nada estoura.
  if (audCtx.state === "suspended") retomarAudio();
  // O orçamento é por QUADRO de desenho (`tick`), não por segundo: é o que impede um pico
  // instantâneo de virar uma parede de som, sem limitar a cadência normal de nada.
  if (audVozesQuadro !== tick) { audVozesQuadro = tick; audVozes = 0; }
  if (audVozes >= 6) return null;
  audVozes++;
  return audCtx;
}
// Ligado no primeiro gesto do usuário, venha ele de onde vier. Chamado de dentro dos
// pointerdown que já existem, e envolto em try/catch porque um AudioContext recusado não pode
// ser a razão de o jogo não abrir.
function acordarAudio() {
  if (audCtx) { if (audCtx.state === "suspended") retomarAudio(); return; }
  try {
    const C = window.AudioContext || (window as any).webkitAudioContext;
    if (!C) return;
    audCtx = new C();
    audMestre = audCtx.createGain();
    audMestre.gain.value = AUD_VOL;
    audMestre.connect(audCtx.destination);
    // Um segundo de ruído branco, gerado UMA vez e reutilizado por todo BufferSource. Gerar
    // ruído por evento seria alocar 44.100 floats para tocar 30 ms deles.
    const n = Math.floor(audCtx.sampleRate * 0.5);
    audRuido = audCtx.createBuffer(1, n, audCtx.sampleRate);
    const d = audRuido.getChannelData(0);
    for (let i = 0; i < n; i++) d[i] = Math.random() * 2 - 1;
  } catch (e) { audCtx = null; audMestre = null; }
}
// UMA NOTA. Oscilador -> ganho com envelope -> mestre. `ataque` curto mas nunca zero: um
// envelope que salta de 0 ao pico num sample estala, e estalo é a coisa que cansa mais rápido.
// Tudo é agendado no relógio do áudio e o nó se desliga no fim, então não há timer, não há
// laço e não há nó vivo depois do som.
function nota(freq, dur, vol, tipo?, ataque?, freqFim?) {
  const c = audioPronto(); if (!c || !audMestre) return;
  const t = c.currentTime, atk = ataque === undefined ? 0.006 : ataque;
  const o = c.createOscillator(), g = c.createGain();
  o.type = tipo || "triangle";
  o.frequency.setValueAtTime(freq, t);
  // Uma varredura de altura quando pedida — é o que faz o pulo subir e o tique não ser plano.
  if (freqFim) o.frequency.exponentialRampToValueAtTime(Math.max(20, freqFim), t + dur);
  g.gain.setValueAtTime(0.0001, t);
  g.gain.exponentialRampToValueAtTime(Math.max(0.0002, vol), t + atk);
  // Decaimento exponencial até quase zero e um degrau para zero no fim: `exponentialRamp`
  // nunca chega a 0, e deixar o ganho parado em 0,0001 seria um zumbido somado a cada voz.
  g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
  g.gain.setValueAtTime(0, t + dur);
  o.connect(g); g.connect(audMestre);
  o.start(t); o.stop(t + dur + 0.02);
  o.onended = function () { try { o.disconnect(); g.disconnect(); } catch (e) {} };
}
// UM SOPRO DE RUÍDO, passado por um filtro. É o passo, é a aterrissagem e é o farfalhar — a
// diferença entre os três é a frequência do filtro e o tempo do envelope, nada mais.
function sopro(dur, vol, corte, q, passaAlta?) {
  const c = audioPronto(); if (!c || !audMestre || !audRuido) return;
  const t = c.currentTime;
  const s = c.createBufferSource(), f = c.createBiquadFilter(), g = c.createGain();
  s.buffer = audRuido;
  // Começa num ponto aleatório do meio segundo gravado: dois passos seguidos nunca são o
  // mesmo recorte de ruído, e é isso que impede a passada de soar como um loop.
  const off = Math.random() * 0.4;
  f.type = passaAlta ? "highpass" : "bandpass";
  f.frequency.value = corte; f.Q.value = q;
  g.gain.setValueAtTime(0.0001, t);
  g.gain.exponentialRampToValueAtTime(Math.max(0.0002, vol), t + 0.004);
  g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
  g.gain.setValueAtTime(0, t + dur);
  s.connect(f); f.connect(g); g.connect(audMestre);
  s.start(t, off, dur + 0.05); s.stop(t + dur + 0.05);
  s.onended = function () { try { s.disconnect(); f.disconnect(); g.disconnect(); } catch (e) {} };
}

// A ESCALA. Pentatônica maior em lá — as cinco notas que não têm meio-tom entre si, então
// qualquer sequência delas, em qualquer ordem e em qualquer velocidade, continua consonante.
// É a razão TÉCNICA de o som de alcançar não cansar: ele toca dezenas de vezes por minuto e
// nunca repete a mesma altura duas vezes seguidas, mas também nunca produz um intervalo feio.
const AUD_ESCALA = [440.00, 493.88, 587.33, 659.25, 739.99, 880.00];
let audGrau = 0;
// ALCANÇAR — o verbo. Uma nota curta de triângulo, ataque suave, 110 ms, subindo pela
// pentatônica e voltando ao começo. Soa como um dedo numa marimba pequena: madeira, não metal,
// e sem nenhuma componente de choque. O grau anda +2 a cada toque, então a sequência é um
// arpejo aberto em vez de uma escada, e volta ao grave antes de ficar estridente.
// `contato` diz se aquele gesto chegou em alguém. Alcançar o vazio é 65% da renda hoje, então
// ele NÃO pode ser mudo — mas também não pode soar igual a chegar em alguém, ou o som deixa de
// informar. A diferença é de timbre e não de volume: com contato entra a quinta acima, que dá
// corpo; sem contato fica a nota nua e mais curta, e lê como um gesto no ar.
function somAlcance(contato?) {
  const f = AUD_ESCALA[audGrau % AUD_ESCALA.length];
  audGrau = (audGrau + 2) % (AUD_ESCALA.length * 3);
  nota(f, contato ? 0.11 : 0.075, contato ? 0.30 : 0.17, "triangle", 0.004);
  if (contato) nota(f * 1.5, 0.055, 0.09, "sine", 0.004);
}
// ATENDIDA ATÉ O FIM. Não é um som de queda: é um intervalo que RESOLVE, dois graus subindo
// com 60 ms entre eles, e o segundo mais longo que o primeiro. Lê como "pronto", como quem
// termina de ajudar alguém. É deliberadamente a mesma família tímbrica do alcance, uma oitava
// acima, para que a orelha entenda que é a conclusão daquilo e não outro evento.
function somAtendida() {
  const f = AUD_ESCALA[audGrau % AUD_ESCALA.length];
  nota(f, 0.09, 0.22, "triangle", 0.004);
  setTimeout(function () { nota(f * 1.5, 0.22, 0.24, "triangle", 0.006); }, 60);
}
// RECOLHER. Curto e claramente outra coisa: duas senoides brilhantes, quase juntas, subindo.
// 70 ms no total. É metal e não madeira, e é o único som agudo do jogo — foi assim que ficou
// distinto do alcance sem precisar ser mais alto que ele.
function somDrop() {
  nota(880, 0.06, 0.16, "sine", 0.003);
  setTimeout(function () { nota(1318.5, 0.09, 0.14, "sine", 0.003); }, 45);
}
// PULAR. Uma varredura de 300 para 700 Hz em 130 ms, senoide. Sobe junto com ela e some antes
// do topo do arco, então o ouvido guarda a impulsão e não o voo.
function somPulo() { nota(300, 0.13, 0.15, "sine", 0.004, 700); }
// ATERRISSAR. Duas camadas: um baque grave (senoide caindo de 150 para 60 Hz em 90 ms) e um
// sopro de terra por cima (ruído em passa-baixa larga, 70 ms). Junto soa como sola em chão de
// terra batida, e não como uma batida de bumbo.
function somPouso() {
  nota(150, 0.09, 0.22, "sine", 0.004, 60);
  sopro(0.07, 0.10, 380, 0.7);
}
// PASSO. O mais sutil de todos e o mais fácil de errar: 22 ms de ruído em passa-banda a 900 Hz
// com Q baixo, a um sexto do volume de um alcance. Sozinho quase não se ouve; o que se ouve é
// a CADÊNCIA. Sai no mesmo evento que troca o quadro do sprite, então ele casa com o pé por
// construção — a passada já é escolhida pela distância percorrida, e não pelo relógio.
function somPasso() { sopro(0.022, 0.05, 900, 0.9); }
// VIRADA DE ERA. Um momento, não um efeito: três notas da pentatônica soando em arpejo com
// 130 ms entre elas e decaimento de 1,1 s, então elas se sobrepõem e o que fica é um acorde
// que abre. É o único som longo do jogo, e o único que usa mais de duas vozes.
function somEra() {
  [0, 2, 4].forEach(function (g, i) {
    setTimeout(function () { nota(AUD_ESCALA[g] * 0.5, 1.1, 0.20, "triangle", 0.03); }, i * 130);
  });
}
// TIQUE DA FALA. 12 ms, onda quadrada bem baixa em 1,4 kHz, e só a cada TRÊS letras — a cada
// letra vira metralhadora, e foi medido lendo: a 18 ms por letra, uma a uma dá 55 tiques por
// segundo. A cada três dá 18, que é a cadência de quem digita depressa.
function somTique() { nota(1400, 0.012, 0.05, "square", 0.002); }
// CHEGOU ALGUÉM. Discreto: é aviso, não susto. Uma nota grave e curta (220 Hz, 70 ms,
// triangular, ataque lento de 12 ms para não ter transiente), no fundo da mistura. Quem estava
// olhando percebe; quem não estava, não leva sobressalto.
function somChegada() { nota(220, 0.07, 0.09, "triangle", 0.012); }

// Offline used to bill one frozen rate for the whole night: efficiency was read at save
// time and multiplied by twelve hours. Go to bed right after switching to GO FAST with a
// rested team and you were paid the rested rate while the team wore out in their sleep.
// Tiredness is exact in closed form, so the fix is to let the gain move with it — the
// slices are small enough that the rate barely changes inside one, and stepping the same
// simular() keeps offline and online on a single code path, ramp included.
function simularOffline(total) {
  const PASSO = 1;
  let ganho = 0, resto = total;
  while (resto > 0) {
    const p = Math.min(PASSO, resto);
    // nothing accrues while away: passive income went with the projects
    resto -= p;
  }
  return ganho;
}

// ---------- save / load / offline ----------
function salvar() {
  S.salvoEm = Date.now();
  // write only what the schema will read back: a save never carries a field the loader
  // would discard, so what is on disk and what the game runs on are the same shape
  const fora = {};
  for (const chave in ESQUEMA_SAVE) fora[chave] = S[chave];
  try { localStorage.setItem(CHAVE_JOGO, JSON.stringify(fora)); } catch (e) {}
}
// ===== OS CAPÍTULOS =====
// Cada um tem NOME (o rótulo do HUD e o título da fala), QUANDO (onde e em que século), e as
// duas falas: a ABERTURA, que a pessoa lê ao entrar no capítulo, e o FECHO, que ela lê ao
// completá-lo.
//
// Isto NÃO vive em `TEXTOS`, e a separação é a mesma que já vale para `FONTES` e `MOMENTOS`:
// `TEXTOS` é ficção autoral e o smoke test proíbe dígito lá dentro, porque número solto numa
// frase de jogo lê como fato. Estas falas PRECISAM de ano — 1500, 1630, 2022 — porque são
// afirmações com procedência, e a procedência está na tela DE ONDE VEM e no NOTES.md.
// Misturar as duas listas apagaria a regra que protege as duas.
//
// O texto abaixo é do dono, palavra por palavra. Não se completa, não se resume e não se
// "melhora a transição" — falta de linha se relata, não se preenche.
//
// UMA EXCEÇÃO, pedida por ele: a ÚLTIMA linha de cada `abertura` apresenta os objetos daquele
// capítulo, porque quem entrava via fruta, peixe e muda passando sem nenhuma explicação. Ela é
// escrita sob uma regra estreita e a regra vale para quem mexer nela depois: essa linha
// DESCREVE O QUE ESTÁ NA TELA — o que vem pela rua e o que o contador faz com aquilo — e nunca
// afirma fato histórico novo. "Aqui vem cesto de legumes" é seguro; qualquer frase sobre o que
// um povo comia, plantava ou usava é afirmação com procedência e exige fonte no NOTES.md.
// Na dúvida, descreva a mecânica e não a história.
//
// `aberturaImg` é a associação FALA → IMAGEM DE CONTEXTO, e é uma lista do MESMO tamanho da
// `abertura`, posição por posição. Cada item é uma chave de `CTX_B64` ou `null`.
//
// Três regras que se leem na lista e vale escrever por extenso:
//  - **Repetir é normal.** Duas falas seguidas sobre o mesmo lugar ficam na mesma imagem: a
//    troca só acontece quando o ASSUNTO muda, e trocar por trocar transforma leitura em
//    apresentação de slides.
//  - **`null` não é buraco.** As falas que explicam o que fazer e o que vem pela rua descrevem
//    a TELA. Cobrir a tela com uma paisagem bonita justo nelas seria esconder o que a frase
//    manda olhar. Nessas, a imagem sai e o jogo aparece — que é o estado normal desta tela.
//  - **A imagem não pode afirmar mais que o texto.** Ela ilustra a frase que está sendo lida,
//    e nada além. Paisagem sem gente é o que permite isso; ver §2 e o cabeçalho de `CTX_B64`.
//
// Chave que não existe em `CTX_B64` é tratada como `null` — é assim que o capítulo 3 fica
// escrito e inerte enquanto a arte dele não chega.
const EPOCAS = [
  {
    // PINDORAMA — decisão do dono (2026-08-07, "pode pegar em referências de história com
    // bibliografia de negros ou indígenas"): o nome que as línguas tupi davam a esta terra,
    // vivo até hoje na fala do movimento indígena. O capítulo deixa de se definir pela
    // chegada dos outros. Fonte no NOTES.md (Navarro 2013; uso contemporâneo em Krenak).
    nome: "PINDORAMA",
    quando: "litoral atlântico · século XVI",
    cenas: 2, lugar: "litoral",
    abertura: [
      "Este lugar é o litoral atlântico. Muito antes de qualquer navio europeu aparecer no horizonte, já havia gente aqui.",
      "Os Tupinambá viviam nesta costa. Plantavam mandioca, pescavam, cuidavam de roçados. Tinham língua própria. E não estavam sozinhos: esta terra era de centenas de povos, com centenas de línguas.",
      "Nada disso era o começo de nada. Era a vida acontecendo, do jeito dela.",
      "Aqui você vai fazer o trabalho do dia. O que passa precisa de alguém. Alcance quem puder.",
      "Pela mata vem cacho de fruta no galho, peixe e muda de plantar — três coisas diferentes, e cada uma enche um contador lá em cima. Folha solta no ar também conta, mas essa só cai para quem pula."
    ],
    // a mata na primeira frase, porque "este lugar" é ela; o roçado entra quando o texto fala
    // de plantar e pescar, e fica na frase seguinte, que ainda é sobre essa vida acontecendo.
    aberturaImg: ["cap1-mata", "cap1-rocado", "cap1-rocado", null, null],
    fecho: [
      "Em 1500 chegaram navios. Depois deles vieram mais.",
      "O que os europeus escreveram sobre este lugar é quase tudo o que sobrou por escrito — e eles escreviam para leitores europeus, não para contar quem estava aqui.",
      "Ao longo de mais de três séculos, milhões de pessoas seriam trazidas da África à força para trabalhar nesta terra.",
      "Algumas fugiram. E o que elas construíram tem nome."
    ]
  },
  {
    nome: "PALMARES",
    quando: "serra da Barriga, Alagoas · século XVII",
    cenas: 2, lugar: "palmares",
    abertura: [
      "Isto aqui é a serra da Barriga, no que hoje se chama Alagoas.",
      "A partir de mais ou menos 1630, milhares de pessoas que fugiram da escravidão subiram estas encostas e construíram povoados.",
      "Não eram esconderijos. Eram vilas, com roça, comércio e defesa — e resistiram por décadas a mais de vinte expedições militares.",
      "Aqui, alcançar é acolher. Quem chega vem ficar.",
      "Aqui não vem coisa pela estrada: vem gente. Quem você alcança vira e passa a andar com você. O que ela trazia na mão fica no chão, e são os mesmos três contadores do capítulo anterior."
    ],
    // a serra segura as duas primeiras: a primeira a nomeia, a segunda fala de subir estas
    // encostas — é a mesma imagem. A roça entra em "eram vilas, com roça, comércio e defesa",
    // que é a frase que desmonta a ideia de esconderijo, e é isso que a imagem mostra.
    aberturaImg: ["cap2-serra", "cap2-serra", "cap2-roca", null, null],
    fecho: [
      "Palmares foi destruída em 1694. Zumbi foi morto em 20 de novembro de 1695 — a data é hoje o Dia da Consciência Negra.",
      "Quase tudo que se sabe sobre a forma daquele lugar vem dos documentos de quem foi atacá-lo. Até os nomes chegaram tortos: a pesquisa recente lê \"Gana Zumba\" onde os livros escreviam \"Ganga Zumba\".",
      "A serra da Barriga é patrimônio tombado hoje. Levou quase três séculos.",
      "E os povos do primeiro capítulo? Continuam aqui."
    ]
  },
  {
    nome: "AINDA AQUI",
    quando: "terra indígena demarcada · hoje",
    cenas: 2, lugar: "hoje",
    abertura: [
      "Este é o presente. A mesma mata, cinco séculos depois.",
      "O Censo de 2022 contou 1,69 milhão de indígenas no Brasil, de 391 etnias, falando 295 línguas. Não é passado nenhum.",
      "Os Tupinambá de Olivença, no sul da Bahia, tiveram a portaria de demarcação da terra deles assinada em 2025 — depois de um processo que ficou parado por mais de uma década.",
      "O trabalho aqui é o mesmo do primeiro capítulo. Colher, plantar, cuidar. Não é coincidência.",
      "Pela estrada vem muda de plantar, galão de água e cesto de legumes — as mesmas três coisas do começo, com a cara de agora."
    ],
    // ESCRITO E INERTE: as duas peças do capítulo 3 ainda não chegaram em `assets/entrada`,
    // então `CTX_B64` não tem estas chaves e `trocarCtx` as trata como `null` — o capítulo
    // roda hoje sem imagem, sem erro e sem furo. No dia em que `ctx-cap3-demarcada.png` e
    // `ctx-cap3-disputa.png` caírem na pasta, `node test/inline-contexto.js` liga as duas
    // sozinho e nenhuma linha aqui precisa mudar.
    aberturaImg: ["cap3-demarcada", "cap3-demarcada", "cap3-disputa", null, null],
    fecho: [
      "A demarcação não é um final feliz. É uma disputa em curso, e ela continua depois que você fecha o jogo.",
      "Se alguma coisa aqui te deu vontade de saber mais, a tela DE ONDE VEM lista as fontes de tudo o que este jogo afirma.",
      "Inclusive onde elas discordam entre si."
    ]
  }
];
// Quantas cenas cada época ocupa é DADO da época (`cenas` acima), não aritmética espalhada.
// Tudo que antes fazia `*2`, `/2` ou `min(2, …)` passa pelas funções abaixo — adicionar um
// capítulo é acrescentar um objeto em EPOCAS (e a arte dele), e nenhuma conta muda.
// Uma conta só, escrita num lugar só, para o HUD, a fala e a tela A HISTÓRIA nunca
// discordarem sobre em que capítulo alguém está.
const EPOCA_CENA0: number[] = [];      // primeira cena de cada época (soma-prefixo de `cenas`)
let TOTAL_CENAS = 0;
EPOCAS.forEach(function (ep) { EPOCA_CENA0.push(TOTAL_CENAS); TOTAL_CENAS += ep.cenas; });
// A máscara cheia das falas vistas: um bit por época. O ESQUEMA_SAVE valida contra ela.
const MASCARA_EPOCAS = (1 << EPOCAS.length) - 1;
// `S.acolhidos` nasce vazio porque S é declarado antes de EPOCAS; aqui ele ganha o tamanho
// certo — uma posição por época, começando em zero.
while (S.acolhidos.length < EPOCAS.length) S.acolhidos.push(0);
// ===== OS MARCOS NO CHÃO DO CAPÍTULO 2 (protótipo travessia+lugar-vivo, JOGABILIDADE.md) =====
// Três placas de madeira fincadas na estrada de Palmares. Cada uma materializa um momento
// que JÁ EXISTE na LINHA_TEMPO (o vão XVI→XVII, `cena: 2`) — nenhum texto histórico novo.
// A escolha abaixo é ÍNDICE DENTRO DESSE VÃO: 0 = O açúcar, 2 = A travessia forçada,
// 3 = A guerra que abriu a serra — a última com o sujeito em quem resistiu, critério do
// historiador que a própria LINHA_TEMPO registra.
const MARCOS_CAP2_ESCOLHA = [0, 2, 3];
const MASCARA_MARCOS = (1 << MARCOS_CAP2_ESCOLHA.length) - 1;
// Teto de armazenamento de `acolhidos`, derivado do ritmo real da rua e nunca relaxado:
// uma chegada nasce a cada ≥ 51 px de mundo (0,65 × mobVao), então 9999 acolhidas exigem
// ~510 mil px — mais de 1,8 h de corrida contínua DENTRO de um capítulo. Acima disso é
// save adulterado, e cai no teto. O desenho nunca passa de 6 figuras (o excedente é texto),
// então o teto não põe multidão nenhuma na tela.
const ACOLHIDOS_TETO = 9999;
function cenarioDaEpoca(e) { return EPOCA_CENA0[Math.max(0, Math.min(EPOCAS.length - 1, e | 0))]; }
function epocaDoCenario(i) {
  let e = EPOCAS.length - 1;
  while (e > 0 && (i | 0) < EPOCA_CENA0[e]) e--;
  return e;
}
function epocaAtual() { return epocaDoCenario(cenarioAtual()); }

// Every field a save is allowed to carry, with the shape it has to be in. num() clamps into
// a range and rejects NaN and Infinity; bool() and um() speak for themselves. A field missing
// from this table cannot enter the game, whatever the stored JSON says.
const ESQUEMA_SAVE = {
  energia:      { tipo: "num", min: 0, max: 1e15, pad: 0 },
  energiaTotal: { tipo: "num", min: 0, max: 1e15, pad: 0 },
  modo:         { tipo: "um", entre: ["limpo", "carvao"], pad: "limpo" },
  u1:           { tipo: "bool", pad: false },
  u2:           { tipo: "bool", pad: false },
  u3:           { tipo: "bool", pad: false },
  u4:           { tipo: "bool", pad: false },
  // O teto é o número de cenas que EPOCAS declara, não um literal: capítulo novo entra na
  // lista e o esquema passa a aceitar a cena dele sozinho — sem relaxar nada para as demais.
  cenario:      { tipo: "num", min: 0, max: TOTAL_CENAS - 1, pad: 0 },
  // A média móvel do que você alcançou. Faixa fechada em 0..1 e padrão 1: um save adulterado
  // com -9 ou com "seco" cai no mundo INTEIRO, nunca no seco. Se um campo vai ter fallback,
  // que ele erre para o lado que não pune ninguém.
  cuidado:      { tipo: "num", min: 0, max: 1, pad: 1 },
  // As falas já vistas, um bit por capítulo — a máscara cheia deriva de EPOCAS.length
  // (MASCARA_EPOCAS), então capítulo novo abre o bit dele sozinho. Tipo próprio, e não
  // "num", porque APARAR não serve aqui: 999 aparado vira a máscara cheia, que é "já viu
  // tudo", e isso trancaria o conteúdo histórico — a razão de o jogo existir — por causa de
  // um save torto. Valor fora da faixa cai no padrão 0, que erra para o lado de MOSTRAR: no
  // pior caso alguém relê uma fala, nunca perde uma.
  aberturas:    { tipo: "bits", min: 0, max: MASCARA_EPOCAS, pad: 0 },
  fechos:       { tipo: "bits", min: 0, max: MASCARA_EPOCAS, pad: 0 },
  // O interruptor de som. `bool` é o tipo mais fechado que existe aqui: qualquer coisa que não
  // seja o literal `true` cai em false. O padrão do ESQUEMA é portanto DESLIGADO, e é o lado
  // certo para errar — um save torto pode calar o jogo, nunca fazer barulho sem permissão. O
  // padrão de quem nunca jogou continua sendo ligado, porque vem de `S` e não daqui.
  som:          { tipo: "bool", pad: false },
  // Quantas andam com você. Faixa fechada em 0..GRUPO_MAX e padrão 0: um save adulterado com
  // 900 não põe novecentas figuras na tela, e errar para 0 é o lado que não inventa gente.
  grupo:        { tipo: "num", min: 0, max: 5, pad: 0 },
  // Uma posição por época, faixa fechada em 0..ACOLHIDOS_TETO (derivação no próprio teto) e
  // padrão 0 por elemento: um save adulterado com "muitas" ou com -3 erra para o lado que
  // não inventa gente. O tamanho vem de EPOCAS.length — capítulo novo abre a posição dele
  // sozinho, sem relaxar as demais.
  acolhidos:    { tipo: "lista", n: EPOCAS.length, min: 0, max: ACOLHIDOS_TETO, pad: 0 },
  // Os marcos do chão já falados, um bit por marco. Mesmo tipo (e mesmo motivo) de
  // `aberturas`: aparar 999 para a máscara cheia calaria as três placas — valor fora da
  // faixa cai no padrão 0, que erra para o lado de FALAR de novo, nunca de calar.
  marcos:       { tipo: "bits", min: 0, max: MASCARA_MARCOS, pad: 0 },
  salvoEm:      { tipo: "num", min: 0, max: 4e12, pad: 0 }
};
function valida(regra, v) {
  if (regra.tipo === "num") {
    if (typeof v !== "number" || !isFinite(v)) return regra.pad;
    return Math.min(regra.max, Math.max(regra.min, v));
  }
  // Máscara de bits: inteira, dentro da faixa, ou o padrão. Sem aparar — ver o comentário
  // em ESQUEMA_SAVE: aparar para o teto é exatamente o erro que não se pode cometer aqui.
  if (regra.tipo === "bits") {
    if (typeof v !== "number" || !isFinite(v)) return regra.pad;
    const n = Math.floor(v);
    return (n >= regra.min && n <= regra.max) ? n : regra.pad;
  }
  // Lista de números de tamanho FIXO: cada elemento passa pela mesma régua de "num", e o
  // que faltar, sobrar ou não for número finito vira o padrão. O comprimento é sempre
  // `regra.n` — um save com array de 900 posições sai daqui com EPOCAS.length, nem uma a mais.
  if (regra.tipo === "lista") {
    const fora: number[] = [];
    for (let i = 0; i < regra.n; i++) {
      const el = Array.isArray(v) ? v[i] : undefined;
      fora.push(typeof el === "number" && isFinite(el)
        ? Math.min(regra.max, Math.max(regra.min, Math.floor(el))) : regra.pad);
    }
    return fora;
  }
  if (regra.tipo === "bool") return v === true;
  if (regra.tipo === "um") return regra.entre.indexOf(v) >= 0 ? v : regra.pad;
  return regra.pad;
}
function carregar() {
  let bruto: string | null = null;
  try { bruto = localStorage.getItem(CHAVE_JOGO); } catch (e) {}
  if (!bruto) return;
  let lido;
  try { lido = JSON.parse(bruto); } catch (e) { return; }
  if (!lido || typeof lido !== "object" || Array.isArray(lido)) return;
  for (const chave in ESQUEMA_SAVE) {
    if (Object.prototype.hasOwnProperty.call(lido, chave)) {
      S[chave] = valida(ESQUEMA_SAVE[chave], lido[chave]);
    }
  }
  // impact can never be less than what is in hand: a save claiming otherwise is inconsistent
  if (S.energiaTotal < S.energia) S.energiaTotal = S.energia;
  // A save from before the cleanup still carries a project count and the tiredness those
  // projects had built up. Neither exists now, so they are dropped on load rather than left
  // to quietly divide the tap gain with no readout to explain it.
  // old saves predate the resource layer; missing objects read back as their empty shape
  if (!S.recursos || typeof S.recursos !== "object") S.recursos = { flor: 0, agua: 0, refeicao: 0 };
  // O desenho abre já no estado salvo em vez de secar/reverdecer na cara de quem entrou: a
  // suavização existe para a transição DENTRO da partida, não para a abertura dela.
  cuidadoVisto = S.cuidado;
  semearGrupo();       // a fila volta como estava: quem veio ficar continua andando junto
  const dt = Math.min((Date.now() - S.salvoEm) / 1000, CFG.capOfflineHoras * 3600);
  voltouDepoisDe = dt;
  mostrarRetorno(dt);
}

// ===== A TELA DE RETORNO — "enquanto você esteve fora" (JOGABILIDADE.md, passo 3) =====
// Um papel de campo, no mesmo material da caixa de fala, que abre ao voltar com mais de um
// minuto fora e lista o que o LUGAR tem a dizer. Regra dura: nenhum dígito inventado —
// cada número aqui é lido do estado real (tempo medido, bônus de dias que já existe, fila
// salva, acolhidas salvas). Não há produção offline nesta economia, e a tela não finge que
// houve: diz que a estrada esperou. Fecha num toque.
// Substitui a tira #offline, que era texto do tema anterior ("AWAY", "the neighbourhood").
// Tudo entra como TEXTO, nó a nó — nada aqui pode virar marcação.
function mostrarRetorno(dt) {
  if (dt <= 60) return;
  const el = document.getElementById("retorno");
  if (!el) return;
  const lista = document.getElementById("retLista");
  if (!lista) return;
  lista.textContent = "";
  const linha = function (txt) {
    const d = document.createElement("div");
    d.className = "retLinha";
    d.textContent = txt;
    lista.appendChild(d);
  };
  const h = Math.floor(dt / 3600), m = Math.floor((dt % 3600) / 60);
  linha("Você ficou fora por " + (h > 0 ? h + "h" + String(m).padStart(2, "0") : m + " min") + ".");
  if (R.dias.length > 1) {
    linha("Dia " + R.dias.length + " de travessia — o caminho te conhece: tudo vale ×"
      + bonusDias().toFixed(2) + ".");
  }
  const fila = S.grupo | 0;
  if (fila > 0) {
    linha(fila === 1 ? "Uma pessoa continua andando com você."
      : fila + " pessoas continuam andando com você.");
  }
  const vivendo = S.acolhidos.reduce(function (a, b) { return a + (b | 0); }, 0);
  if (vivendo > 0) {
    linha(vivendo === 1 ? "Uma pessoa acolhida vive no lugar que vocês abriram."
      : vivendo + " pessoas acolhidas vivem no lugar que vocês abriram.");
  }
  // a verdade da economia deste jogo, dita em vez de uma produção inventada
  linha("A estrada esperou. O que chega, chega para quem está aqui.");
  pixelRotulo($("retTit"), "ENQUANTO VOCÊ ESTEVE FORA", 2, "#5c3210");
  el.classList.add("aberto");
  el.setAttribute("aria-hidden", "false");
}
function fecharRetorno() {
  const el = document.getElementById("retorno");
  if (!el) return;
  el.classList.remove("aberto");
  el.setAttribute("aria-hidden", "true");
}

// ---------- retention (this device only: no service, nothing personal) ----------
// The prototype exists to answer "does the loop hold someone for three days?", so the
// answer lives in its own key: passing the torch wipes S, and a corrupted game save
// should not take the measurement down with it.
// bumped when the cleanup removed projects, the torch and the whole economy those fed:
// a save from before that carries totals no version of this game could have produced.
const CHAVE_JOGO = "jogo_brasil_v1";
const CHAVE_RET = "jogo_brasil_retencao";
let R: Retencao = { dias: [], segundos: 0, tochas: 0 };
function diaLocal() {
  const d = new Date();
  return d.getFullYear() + "-" + String(d.getMonth() + 1).padStart(2, "0")
    + "-" + String(d.getDate()).padStart(2, "0");
}
function salvarRetencao() {
  try { localStorage.setItem(CHAVE_RET, JSON.stringify(R)); } catch (e) {}
}
function marcarDia() {
  const d = diaLocal();
  if (R.dias.indexOf(d) < 0) {
    const primeira = R.dias.length === 0;
    R.dias.push(d); R.dias.sort(); salvarRetencao();
    if (!primeira) diaNovo = true;   // a day the player came *back* — worth a welcome
  }
}
function carregarRetencao() {
  let bruto: string | null = null;
  try { bruto = localStorage.getItem(CHAVE_RET); } catch (e) {}
  if (bruto) { try { Object.assign(R, JSON.parse(bruto)); } catch (e) {} }
  // a hand-edited or half-written record must not take the game down
  if (!Array.isArray(R.dias)) R.dias = [];
  R.dias = R.dias.filter(function (d) { return typeof d === "string" && /^\d{4}-\d\d-\d\d$/.test(d); });
  if (typeof R.segundos !== "number" || !isFinite(R.segundos) || R.segundos < 0) R.segundos = 0;
  if (typeof R.tochas !== "number" || !isFinite(R.tochas) || R.tochas < 0) R.tochas = 0;
  marcarDia();
}
