function montarCompletude() {
  const box = $("listaCenas");
  box.textContent = "";
  const ate = cenarioAtual();
  // A coluna: o fio é filho DELA, não do rolo — absoluto num contêiner que tem a altura do
  // conteúdo inteiro, para descer junto com a rolagem em vez de ficar parado no vidro.
  const col = document.createElement("div");
  col.id = "ltCol";
  const fio = document.createElement("div");
  fio.id = "ltFio";
  col.appendChild(fio);
  const sub = function (pai, cls, txt) {
    const d = document.createElement("div");
    d.className = cls; d.textContent = txt;
    pai.appendChild(d); return d;
  };
  // O FIM DA LINHA (usabilidade, achado 8): uma escada de "— ainda não —" repetidos não
  // promete nada — conta a mesma ausência N vezes. Sequências CONSECUTIVAS de momentos
  // não-alcançados (duas ou mais) colapsam numa placa só que diz quantos marcos vêm à
  // frente. Um momento sozinho continua sendo o traço de sempre: um teaser lê; seis são
  // um formulário vazio. Marcos e pontas quebram a sequência — eles têm placa própria.
  const momentoVisto = function (no: NoLinha) {
    return (no.cena != null ? no.cena : no.i!) <= ate;
  };
  const fila: NoLinha[] = [];
  const nos: (NoLinha | { tipo: "mais"; n: number })[] = [];
  const despejarFila = function () {
    if (fila.length >= 2) nos.push({ tipo: "mais", n: fila.length });
    else if (fila.length === 1) nos.push(fila[0]);
    fila.length = 0;
  };
  LINHA_TEMPO.forEach(function (no) {
    if (no.tipo === "momento" && !momentoVisto(no)) { fila.push(no); return; }
    despejarFila();
    nos.push(no);
  });
  despejarFila();
  nos.forEach(function (no) {
    if (no.tipo === "mais") {
      const n = (no as { n: number }).n;
      const m = document.createElement("div");
      m.className = "ltMais";
      const t = document.createElement("div");
      pixelRotulo(t, "E MAIS " + n + (n === 1 ? " MARCO" : " MARCOS") + " À FRENTE", 1, "#332a1a");
      m.appendChild(t);
      col.appendChild(m);
      return;
    }
    if (no.tipo === "antes") {
      // O trecho de cima: o fio já vem de longe. Texto do dono (abertura do capítulo um),
      // resumido sem afirmar nada novo — a redação final é do historiador.
      const a = document.createElement("div");
      a.className = "ltPonta";
      const t = document.createElement("div");
      pixelRotulo(t, "JÁ HAVIA GENTE AQUI", 1, "#b9ad8d");
      a.appendChild(t);
      sub(a, "ltPontaSub", "muito antes de qualquer chegada — e o fio vem de mais longe do que esta tela alcança");
      col.appendChild(a);
    } else if (no.tipo === "vao") {
      // Espaço estrutural: só o fio passando. É onde os marcos futuros se penduram.
      const v = document.createElement("div");
      v.className = "ltVao";
      col.appendChild(v);
    } else if (no.tipo === "marco") {
      const ep = EPOCAS[no.ep!];
      const chegou = ate >= cenarioDaEpoca(no.ep!);
      const m = document.createElement("div");
      m.className = "ltMarco" + (chegou ? "" : " longe");
      const t = document.createElement("div");
      // a placa longe agora é a mesma madeira, encardida (achado 8) — a tinta acompanha
      pixelRotulo(t, chegou ? ep.nome : "AINDA À FRENTE", 2, chegou ? "#2a1a0a" : "#332a1a");
      m.appendChild(t);
      sub(m, "ltMarcoQuando", chegou ? ep.quando : "continue a travessia");
      col.appendChild(m);
    } else if (no.tipo === "momento") {
      // Ou um índice em MOMENTOS, ou um momento próprio (q/t/d/f no nó) — é o que permite
      // pendurar os marcos do historiador nos vãos sem tocar em MOMENTOS nem no layout.
      const mo = no.i != null ? MOMENTOS[no.i] : (no as { q: string; t: string; d: string; f: string });
      const visto = (no.cena != null ? no.cena : no.i!) <= ate;
      const l = document.createElement("div");
      l.className = "ltMomento" + (visto ? " vista" : "");
      const cab = document.createElement("div");
      cab.className = "ltCab";
      const q = document.createElement("span");
      q.className = "ltQ"; q.textContent = visto ? mo.q : "— ainda não —";
      cab.appendChild(q);
      if (visto) {
        const n = document.createElement("span");
        n.className = "ltT"; n.textContent = mo.t;
        cab.appendChild(n);
      }
      l.appendChild(cab);
      // Momento não visto não revela nada além do traço: o que falta é o motivo de voltar,
      // e entregar a lore inteira na primeira sessão gasta o jogo antes de ele começar.
      if (visto) {
        sub(l, "ltD", mo.d);
        sub(l, "ltF", "fonte: " + mo.f);
      }
      col.appendChild(l);
    } else if (no.tipo === "aberto") {
      // O fim que não fecha: o fio segue além do último nó e some pela borda. O texto
      // espelha o fecho do capítulo três — nenhuma afirmação nova.
      const f = document.createElement("div");
      f.className = "ltPonta fim";
      const t = document.createElement("div");
      pixelRotulo(t, "O FIO CONTINUA", 1, "#b9ad8d");
      f.appendChild(t);
      sub(f, "ltPontaSub", "a disputa está em curso — ela segue depois que você fecha o jogo");
      col.appendChild(f);
    }
  });
  box.appendChild(col);
}

// Os rótulos que não mudam, pintados uma vez na carga. Depois disto o chrome inteiro fala a
// fonte do jogo: o que era Arial Black (letra de site, presa ao que o aparelho tiver) vira a
// mesma 5×7 que flutua sobre a rua. Os títulos das telas são lidos do próprio HTML para não
// escrever o mesmo texto em dois lugares.
function pintarRotulos() {
  document.querySelectorAll<HTMLElement>(".telaTit").forEach(function (el) {
    pixelRotulo(el, el.textContent || "", 3, "#ffd98a");
  });
  pixelRotulo($("menuSub"), "um jogo sobre quem já estava aqui", 1, "#efe3c2");
  pixelRotulo($("btnJogar"), "JOGAR", 4, "#221806");
  pixelRotulo($("btnCompletude"), "A HISTÓRIA", 2, "#d9cfae");
  pixelRotulo($("btnFontes"), "DE ONDE VEM", 2, "#d9cfae");
  pixelRotulo($("btnConfig"), "AJUSTES", 2, "#d9cfae");
  ["btnVoltarCap", "btnVoltarComp", "btnVoltarFontes", "btnVoltarCfg"].forEach(function (id) {
    pixelRotulo($(id), "VOLTAR", 2, "#a9a184");
  });
  // a mesma tinta clara da plaquinha da época — o PULAR agora é a mesma madeira escura
  pixelRotulo($("btnFalaPular"), "PULAR", 1, "#c9ab77");
  const mel = document.querySelector<HTMLElement>("#openUpgrades .cn");
  if (mel) pixelRotulo(mel, "MELHORIAS", 1, "#2a2418");
  const men = document.querySelector<HTMLElement>("#abrirMenu .cn");
  if (men) pixelRotulo(men, "MENU", 1, "#2a2418");
  const tSheet = document.querySelector<HTMLElement>("#sheetUpgrades .sheetHead .t");
  if (tSheet) pixelRotulo(tSheet, "MELHORIAS", 1, "#423b2e");
  pixelRotulo($("btnU5"), "APAGAR", 1, "#ffe6df");
  // Os nomes dos upgrades eram o último texto em fonte do sistema dentro do chrome de jogo:
  // viram dois rótulos bitmap empilhados — o efeito grande, o complemento menor embaixo.
  [["cardU1", "×3", "POR ALCANCE"], ["cardU2", "×2", "NO QUE PEGA"],
   ["cardU3", "2/S", "SOZINHOS"], ["cardU4", "×100", "TESTE"],
   ["cardU5", "ZERAR", "TESTE"]].forEach(function (par) {
    const alvo = document.querySelector<HTMLElement>("#" + par[0] + " .nome");
    if (!alvo) return;
    alvo.textContent = "";
    const a = document.createElement("div"), b = document.createElement("div");
    pixelRotulo(a, par[1], 2, "#2a2418");
    pixelRotulo(b, par[2], 1, "#4a4234");
    alvo.appendChild(a); alvo.appendChild(b);
  });
}

function ligarTelas() {
  // o papel da volta fecha num toque em qualquer ponto dele — e o toque não vaza para o jogo
  $("retorno").addEventListener("pointerdown", function (e) {
    e.preventDefault(); e.stopPropagation(); fecharRetorno();
  });
  $("abrirMenu").addEventListener("pointerdown", function (e) {
    e.preventDefault(); e.stopPropagation();
    fecharTudo(); abrirTela("telaMenu");
  });
  // JOGAR não cai direto na rua: quem começa do zero recebe a abertura do capítulo 1 antes de
  // jogar, que é o pedido do dono — o contexto histórico não pode ficar escondido num menu.
  // Quem já leu passa direto, porque `mostrarAbertura()` só fala uma vez por capítulo.
  $("btnJogar").addEventListener("pointerdown", function (e) {
    e.preventDefault();
    // Com UMA era destrancada a tela de eras é uma escolha sem opções (usabilidade,
    // achado 7): JOGAR entra direto no jogo — a abertura do capítulo 1 continua vindo
    // primeiro, porque mostrarAbertura() só fala uma vez e sai da frente de quem já leu.
    // O cenário NÃO é tocado: quem estava no meio da era continua de onde parou.
    // A lista volta a existir sozinha na segunda era, que é quando há escolha de verdade.
    if (epocaAtual() === 0) { fecharTelas(); mostrarAbertura(); return; }
    montarCapitulos(); abrirTela("telaCapitulos");
  });
  $("btnVoltarCap").addEventListener("pointerdown", function (e) { e.preventDefault(); abrirTela("telaMenu"); });
  $("btnCompletude").addEventListener("pointerdown", function (e) { e.preventDefault(); montarCompletude(); abrirTela("telaCompletude"); });
  $("btnConfig").addEventListener("pointerdown", function (e) { e.preventDefault(); montarConfig(); abrirTela("telaConfig"); });
  $("btnVoltarComp").addEventListener("pointerdown", function (e) { e.preventDefault(); abrirTela("telaMenu"); });
  $("btnFontes").addEventListener("pointerdown", function (e) { e.preventDefault(); montarFontes(); abrirTela("telaFontes"); });
  $("btnVoltarFontes").addEventListener("pointerdown", function (e) { e.preventDefault(); abrirTela("telaMenu"); });
  $("btnVoltarCfg").addEventListener("pointerdown", function (e) { e.preventDefault(); abrirTela("telaMenu"); });
  // Toque em qualquer lugar da tela da fala avança — é o gesto do jogo antigo inteiro, e não
  // um botão pequeno num canto. O PULAR se defende sozinho parando o evento antes.
  $("telaFala").addEventListener("pointerdown", function (e) {
    e.preventDefault();
    // durante a cerimônia, o toque a encerra — nunca engole o gesto nem pula a fala junto
    if (emCerimonia()) { fimCerimonia(); return; }
    avancarFala();
  });
  $("btnFalaPular").addEventListener("pointerdown", function (e) {
    e.preventDefault(); e.stopPropagation(); encerrarFala();
  });
  // Ligar/desligar o som. Salva na hora — quem calou o jogo não pode reencontrá-lo falando
  // depois de fechar a aba. E toca uma nota ao LIGAR, nunca ao desligar: é a única confirmação
  // honesta de que a coisa funciona, e ela chega pelo ouvido.
  $("btnSom").addEventListener("pointerdown", function (e) {
    e.preventDefault();
    S.som = !S.som;
    if (S.som) { acordarAudio(); somAlcance(true); }
    salvar();
    montarConfig();
  });
  $("btnApagar").addEventListener("pointerdown", function (e) { e.preventDefault(); zerarJogo(); montarConfig(); });
}
function montarConfig() {
  const d = R.dias.length, m = Math.floor((R.segundos || 0) / 60);
  // O parágrafo era o último texto de tela em sans-serif do sistema (usabilidade, achado
  // 9). Vira papel de campo (CSS em #telaConfig #cfgInfo) com linhas na fonte bitmap —
  // a mesma 5×7 do resto do jogo. Os números são MEDIDOS (retenção), não inventados; a
  // frase da privacidade continua palavra por palavra: ela é um compromisso, não decoração.
  const box = $("cfgInfo");
  box.textContent = "";
  [["DIAS DISTINTOS JOGADOS: " + d, "#33240f"],
   ["TEMPO TOTAL: " + m + " MIN", "#33240f"],
   ["NADA SAI DESTE APARELHO:", "#5c3210"],
   ["O JOGO NÃO TEM REDE.", "#5c3210"]].forEach(function (l) {
    const linha = document.createElement("div");
    pixelRotulo(linha, l[0], 1, l[1]);
    box.appendChild(linha);
  });
  pixelRotulo($("btnSom"), S.som ? "SOM: LIGADO" : "SOM: DESLIGADO", 2, "#f2e8ce");
  pixelRotulo($("btnApagar"), "APAGAR MEU PROGRESSO", 2, "#e8a595");
}


// ===== DE ONDE VEM =====
// Um jogo que afirma história devia mostrar de onde tirou. Esta lista NÃO vive em `TEXTOS`,
// e a separação é deliberada: `TEXTOS` é ficção autoral e o smoke test o proíbe de conter
// dígito, porque número solto numa frase de jogo lê como fato. Fonte é o contrário — ela
// PRECISA de ano, de número de lei, de volume de periódico. São duas naturezas diferentes e
// misturá-las apagaria a regra que protege as duas.
//
// A seção de DÚVIDA existe porque história tem disputa, e fingir que ela é lisa é pior que
// mostrar a costura. Dizer "estas fontes discordam" ensina mais que escolher uma calado.
const FONTES = [
  { g: "POVOS ORIGINÁRIOS" },
  { t: "Manuela Carneiro da Cunha, “Imagens de índios do Brasil: o século XVI”, Estudos Avançados 4(10), 1990 — USP",
    q: "Inventário crítico das fontes quinhentistas, e a demonstração de que elas descrevem preocupações europeias, não realidades indígenas." },
  { t: "IBGE — Censo 2022",
    q: "391 etnias e 295 línguas indígenas, 1,69 milhão de pessoas. É o dado que derruba tratar “índio” como categoria única." },
  { t: "Lei nº 14.402/2022 — Planalto",
    q: "Institui o Dia dos Povos Indígenas e revoga o “Dia do Índio” de 1943. O Estado brasileiro, em lei, adotando o plural." },
  { t: "Enciclopédia Povos Indígenas no Brasil — Tupinambá de Olivença",
    q: "O povo Tupinambá está vivo, no sul da Bahia, com terra em demarcação. Não são passado." },
  { g: "PALMARES" },
  { t: "Documenta Palmares — Silvia Hunold Lara, Unicamp",
    q: "Cerca de 4.400 documentos digitalizados dos séculos XVII a XIX. A própria base avisa que as informações são incompletas e contraditórias." },
  { t: "Silvia H. Lara, “O território dos Palmares”, Afro-Ásia nº 64, 2021 — UFBA",
    q: "Cartografia dos mocambos a partir da documentação primária: Macaco, Subupira, Amaro, Andalaquituche, Osenga." },
  { t: "Lara & Fachin, Guerra contra Palmares: o manuscrito de 1678 — Chão Editora, 2021",
    q: "Paleografia que corrige nomes: “Gana Zumba”, não “Ganga Zumba” — em quimbundo, gana é senhor e ganga é sacerdote." },
  { g: "ONDE AS FONTES DISCORDAM", d: 1 },
  { t: "Quanta gente vivia aqui em 1500?", d: 1,
    q: "Não há consenso. Rosenblat estimou 1 milhão; Hemming, 2,4 milhões — e chamou o próprio número de “pure guess-work”; Denevan, 4,8 milhões. O jogo não escolhe um." },
  { t: "Quantos viviam em Palmares?", d: 1,
    q: "A Fundação Cultural Palmares, órgão federal, afirma cerca de 20 mil. Silvia Lara classifica os números da documentação seiscentista como exagerados." },
  { t: "“Angola Janga” era mesmo o nome?", d: 1,
    q: "Circula como o nome que os palmaristas usavam, mas não localizamos atestação em documento colonial. O estudo mais completo da toponímia não menciona o termo. Por isso o jogo não o usa." }
];
function montarFontes() {
  const box = $("listaFontes");
  box.textContent = "";
  box.style.maxHeight = Math.max(220, window.innerHeight - 260) + "px";
  FONTES.forEach(function (f) {
    if (f.g) { const h = document.createElement("div"); h.className = "fnGrupo"; pixelRotulo(h, f.g, 1, "#d9a441"); box.appendChild(h); return; }
    const d = document.createElement("div");
    d.className = "fnItem" + (f.d ? " fnDuv" : "");
    const t = document.createElement("div"); t.className = "fnT"; t.textContent = f.t as string;
    d.appendChild(t);
    if (f.q) { const q = document.createElement("div"); q.className = "fnQ"; q.textContent = f.q; d.appendChild(q); }
    box.appendChild(d);
  });
}

function fecharTudo() {
  SHEETS.forEach(function (s) { $(s).classList.remove("aberto"); });
  const b = $("openUpgrades"); if (b) b.classList.remove("fechando");
}

// The sheets float just above the controls. Measure that block instead of guessing it, so
// a button that grows a line can never push the menu bar under an open panel again.
function medirControles() {
  const c = $("controls");
  if (!c) return;
  const h = Math.ceil(c.getBoundingClientRect().height) + 16;
  document.documentElement.style.setProperty("--hControles", h + "px");
}

// ---------- main loop ----------
document.addEventListener("DOMContentLoaded", () => {
  fitCanvas();
  // O ÁUDIO SÓ NASCE DEPOIS DE UM TOQUE. Navegador nenhum deixa um AudioContext tocar antes de
  // um gesto, e criar um na carga rende aviso ou erro no console — que o smoke test reprova.
  // Este ouvinte é de CAPTURA, não consome o evento e não impede nada: ele só existe para que
  // o primeiro toque de qualquer natureza (menu, rua, botão) sirva de destravamento. Sai de
  // o primeiro toque de qualquer natureza (menu, rua, botão) sirva de destravamento.
  //
  // Sem `once`, de propósito: se a primeira tentativa falhar — contexto recusado, aba ainda
  // sem permissão — a segunda conserta sozinha. `acordarAudio` sai na primeira linha quando já
  // existe contexto, então o custo permanente é uma comparação por toque.
  ["pointerdown", "touchstart", "keydown"].forEach(function (ev) {
    document.addEventListener(ev, acordarAudio, { capture: true, passive: true });
  });
  document.querySelectorAll<HTMLCanvasElement>("canvas.pi[data-i]").forEach(function (c) { renderIcon(c, c.dataset.i); });
  pintarRotulos();
  // Main attack: tap once, or HOLD to keep swinging — on the button *or* on the world.
  // Both surfaces share ONE repeat timer, so two thumbs cannot double the hit rate: the
  // set of surfaces being held decides whether the timer runs, never how fast it runs.
  const bc = $("btnClique");
  const segurando = new Set();
  let holdT: ReturnType<typeof setInterval> | null = null;
  function comecarHold(src) {
    segurando.add(src);
    if (!holdT) holdT = setInterval(clicar, 145);   // ~7 hits per second while held
    if (src === "btn") bc.classList.add("segurando");
  }
  function soltar(src?) {
    if (src) segurando.delete(src); else segurando.clear();
    if (!segurando.size && holdT) { clearInterval(holdT); holdT = null; }
    if (!segurando.has("btn")) bc.classList.remove("segurando");
  }
  bc.addEventListener("pointerdown", function (e) {
    e.preventDefault();
    clicar();
    comecarHold("btn");
  });
  ["pointerup", "pointercancel", "pointerleave"].forEach(function (ev) {
    bc.addEventListener(ev, function () { soltar("btn"); });
  });
  window.addEventListener("blur", function () { soltar(); });

  // The world is the other half of the same button. A tap on the scene swings exactly
  // like the CTA does — same combo, same leap, same sprout — and on the way there it
  // hits whatever the thumb landed on. With a sheet open the tap only dismisses it, so
  // "tap outside to close" never costs a stray swing.
  function pontoDoMundo(e) {
    const r = cv.getBoundingClientRect();
    return { x: (e.clientX - r.left) / r.width * W, y: (e.clientY - r.top) / r.height * H };
  }
  const algumaAberta = function () { return SHEETS.some(function (s) { return $(s).classList.contains("aberto"); }); };
  // The street is split down the middle: the left half jumps, the right half swings. No line
  // is drawn for it — the halves are the whole of the interface out here, and a player finds
  // them in one tap each. The action button below still swings, and still holds to repeat.
  cv.addEventListener("pointerdown", function (e) {
    e.preventDefault();
    if (algumaAberta()) { fecharTudo(); return; }
    const r = cv.getBoundingClientRect();
    if (e.clientX < r.left + r.width / 2) pular();
    else {
      // Microdica 1 (usabilidade, achado 5): quem tocou a metade direita descobriu o golpe;
      // nada na tela diz que a OUTRA metade pula. Uma linha efêmera perto da personagem,
      // uma vez por sessão, e só enquanto o save é jovem.
      if (!dicaPuloVista && dicasValem()) { dicaPuloVista = true; dicaPuloAte = relogio + 2.8; }
      clicar();
    }
  });
  // owner: the projects sheet is gone, and with it its buy buttons and its copy of the
  // rhythm switch. The rhythm now lives only on the card in the control block.
  $("modeQuick").onclick = () => { definirModo(S.modo === "carvao" ? "limpo" : "carvao"); };
  [1, 2, 3, 4].forEach(function (n) { $("btnU" + n).onclick = () => comprar("u" + n, CFG["custoU" + n]); });
  // owner: the torch, the wall, the epilogue, the projects sheet and the special projects
  // are gone — every button that opened them went with them.
  $("openUpgrades").onclick = function () {
    const folha = $("sheetUpgrades");
    if (folha.classList.contains("aberto")) fecharTudo(); else abrir("sheetUpgrades");
    $("openUpgrades").classList.toggle("fechando", folha.classList.contains("aberto"));
  };
  document.querySelectorAll<HTMLElement>(".fechar").forEach(function (b) {
    b.onclick = function () { $(b.dataset.close!).classList.remove("aberto"); };
  });
  document.addEventListener("pointerdown", function (e) {
    if (e.target === document.body || e.target === document.documentElement) fecharTudo();
  });

  // The first-run guide: its two buttons act on pointerdown and keep the tap to themselves;
  // any other tap dismisses the step WITHOUT consuming the event, so the same tap still
  // reaches the game underneath (this is a capture-phase listener that only sets state). A
  // short grace stops a tap already in flight when a step appears from killing it unread.
  ligarTelas();
  $("btnU5").addEventListener("pointerdown", function (e) { e.preventDefault(); zerarJogo(); });
  // O guia de primeira partida morreu de verdade (usabilidade, achado 5): os três ouvintes
  // que ficaram para trás da migração — chamando dispensarGuia/pularGuia, que não existiam —
  // saíram junto com a marcação #guia e o CSS dele. Quem ensina agora são as microdicas.
  // no zoom, no text selection: this is a game, not a website
  ["gesturestart", "gesturechange", "gestureend"].forEach(function (ev) {
    document.addEventListener(ev, function (e) { e.preventDefault(); });
  });
  document.addEventListener("touchmove", function (e) { if (e.touches.length > 1) e.preventDefault(); }, { passive: false });
  document.addEventListener("dblclick", function (e) { e.preventDefault(); });

  carregarRetencao();   // before the save: the night that just passed is paid at today's rate
  carregarMuro();       // ...and before carregar(), so the wall count is right on the first draw
  carregar();
  // Coming back is an event, not a cold start: after a night away — or on a day you had
  // not played yet — the kitchen has kept a call for you, and it is worth double.
  if (diaNovo || voltouDepoisDe >= CFG.chamadaVolta) {
    chamadaDobrada = true;
    chamadaT = CFG.chamadaIntervalo - 6;
  }
  // O menu abre só quando não há partida em andamento — quem já jogou quer voltar para onde
  // estava, não apertar JOGAR de novo. E esta decisão vem DEPOIS de carregar(): ela morava
  // acima da leitura do save, onde S.energiaTotal ainda era zero para todo mundo, então o
  // menu abria também para quem estava no meio de uma partida.
  // SEMPRE o menu. Antes ele so abria com placar zerado, entao quem ja jogava caia direto na
  // rua sem passar pela porta — e sem ver as eras. O dono pediu que o comeco seja sempre
  // aqui, e faz sentido: e daqui que se ve o que ja se abriu e o que falta.
  // O menu abre SEMPRE. A abertura da era nao dispara mais aqui: ela passou a ser
  // consequencia de ESCOLHER a era na lista, que e o caminho que o dono pediu.
  abrirTela("telaMenu");
  desenhar();
  semearAnuncios();      // adopt current state so the first frames do not shout on load
  medirControles();
  window.addEventListener("resize", medirControles);


  let ultimo = performance.now(), hudAcc = 0, autoAcc = 0, retAcc = 0;
  function frame(agora) {
    const dt = Math.max(0, Math.min(0.25, (agora - ultimo) / 1000));
    ultimo = agora;
    atualizarMobs(dt);
    atualizarGrupo(dt);         // quem já foi acolhida anda junto — capítulo 2 e só ele
    atualizarMarcos();          // as placas da linha do tempo fincadas na estrada (cap. 2)
    atualizarMoradores(dt);     // a faixa final onde as acolhidas vivem (cap. 2)
    suavizarCuidado(dt);        // o desenho persegue a média; a média anda a degraus
    atualizarDrops(dt);
    atualizarChamada(dt);
    verificarAnuncios();
    // Durante a HISTORIA o mundo continua VIVO mas nao CONTA. Ela segue caminhando, a mata
    // segue rolando, e nada disso soma impacto — porque ler nao pode pagar mais que pular
    // num jogo que existe para ensinar.
    //
    // A primeira versao disto era um `return` no laco inteiro, e congelava a personagem.
    // Errado pelo mesmo motivo que estar certo: parar de CONTAR e parar de VIVER sao coisas
    // diferentes, e so a primeira era o pedido.
    if (S.u3 && !contandoParado()) { // U3: neighbours keep helping on their own
      autoAcc += dt * CFG.autoTapsPorSeg;
      let n = Math.min(4, Math.floor(autoAcc));
      autoAcc -= Math.floor(autoAcc);
      while (n-- > 0) {
        // The auto flag is what keeps these off the combo — it was added because auto-taps used to
        // drive the whole three-beat cycle and set her leaping on her own every second. But it
        // also suppressed the bolt, so the upgrade paid out with nothing on screen: the number
        // moved and nothing happened. The bolt is thrown here instead, straight from the
        // helper, so it is visible without touching the combo or the leap.
        clicar(true, true);
        lancarMagia(0, HX - 8, GROUND - 44);
      }
    }
    // Um quadro de sprite tem que durar um número INTEIRO de quadros de tela, senão a cadência
    // manca. Dez por pose andando (6 quadros/s, 38,3 px/s, 2 passos/s) e cinco correndo
    // (12 quadros/s, 76,5 px/s) — o dobro exato, porque correr usa as mesmas poses da caminhada
    // enquanto não houver folha de corrida, e a única coisa que muda é quanto chão passa.
    // A conta mora em velocidadeMundo(), porque as chegadas nascem da mesma distância.
    worldX += dt * velocidadeMundo();
    // rAF stops in a background tab and dt is clamped, so this counts time actually
    // spent playing rather than time the tab sat open
    R.segundos += dt; retAcc += dt;
    if (retAcc > 30) { retAcc = 0; marcarDia(); salvarRetencao(); }
    tick++; animT += dt; relogio += dt;
    if (saltoHora > 0) {        // a virada de era varre ~1 hora de luz em ~2 s
      const p = Math.min(saltoHora, dt * 220);
      relogio += p; saltoHora -= p;
    }
    rolarFundo();               // the painted backdrop travels with him
    drawScene();
    desenharMundo();
    hudAcc += dt;
    if (hudAcc > 0.2) { desenhar(); hudAcc = 0; }
    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
  setInterval(salvar, 10000);
  window.addEventListener("beforeunload", function () { salvar(); salvarRetencao(); });
  document.addEventListener("visibilitychange", function () {
    if (document.hidden) { salvar(); salvarRetencao(); } else { marcarDia(); }
  });
});
